INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status, version,
   display_order, last_verified_at, last_verified_by, word_count)
VALUES
  ('cs_david-souter_intro', 'ent_david-souter', 'biography_intro', 'Introduction', 'David Hackett Souter ( SOO-tər; September 17, 1939 – May 8, 2025) was an American lawyer and jurist who served as an Associate Justice of the Supreme Court of the United States from 1990 to 2009. Appointed by President George H. W. Bush to fill the seat that had been vacated by William J. Brennan Jr., Souter was a member of both the Rehnquist and Roberts courts.
Raised in New England, Souter attended Harvard College; Magdalen College, Oxford; and Harvard Law School. After briefly working in private practice, he moved to public service. He served as a prosecutor in the office of the Attorney General of New Hampshire (1968–1976); as attorney general of New Hampshire (1976–1978); as an associate justice of the New Hampshire Superior Court (1978–1983); as an associate justice of the New Hampshire Supreme Court (1983–1990); and as a judge of the United States Court of Appeals for the First Circuit (1990).
In mid-2009, after Barack Obama took office as U.S. president, Souter announced his retirement from the Court; he was succeeded by Sonia Sotomayor. Souter continued to hear cases by designation at the circuit court level.',
   '["clm_wiki_david-souter_intro"]', '["src_wikidata"]',
   'general', 'en', 'assisted', 'kp-025-migration-0025', 'auto_approved', 1,
   10, unixepoch(), 'wikipedia', 189);

